CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users(id BIGSERIAL PRIMARY KEY,username VARCHAR(100) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE machines(id BIGSERIAL PRIMARY KEY,name VARCHAR(150) NOT NULL,hostname VARCHAR(255) NOT NULL,ssh_port INT NOT NULL DEFAULT 22,operating_system VARCHAR(100),os_version VARCHAR(100),ssh_host_key TEXT,ssh_fingerprint TEXT,fingerprint_verified_at TIMESTAMPTZ,preferred_credential_id BIGINT,created_by BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted_at TIMESTAMPTZ);
CREATE TABLE command_definitions(id BIGSERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL,description TEXT,category VARCHAR(80),action VARCHAR(80),resource_type VARCHAR(80),command_template TEXT NOT NULL,parameters_schema JSONB,pre_check_template TEXT,supported_os VARCHAR(80),min_os_version VARCHAR(40),max_os_version VARCHAR(40),risk_level VARCHAR(20) NOT NULL DEFAULT 'LOW',requires_approval BOOLEAN NOT NULL DEFAULT false,status VARCHAR(30) NOT NULL DEFAULT 'PENDING',source VARCHAR(30) NOT NULL DEFAULT 'USER',embedding vector(384),embedding_provider VARCHAR(100),embedding_model VARCHAR(150),created_by BIGINT NOT NULL REFERENCES users(id),approved_by BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),approved_at TIMESTAMPTZ);
CREATE INDEX idx_machines_created_by ON machines(created_by); CREATE INDEX idx_commands_status ON command_definitions(status); CREATE INDEX idx_commands_category ON command_definitions(category);
